SELECT jsonb_build_object(
'captured_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),
'user',(SELECT jsonb_build_object('id',id,'is_admin',coalesce(is_admin,false)) FROM public.tb_usuarios WHERE id=492),
'campaign',(SELECT jsonb_build_object('id',id,'code',codigo,'status',status,'version',version,'product_id',produto_id,'benefit_percent',beneficio_percentual,'benefit_product_id',beneficio_produto_id) FROM estudo.campanhas WHERE id=1),
'voucher',(SELECT jsonb_build_object('id',id,'campaign_id',campanha_id,'status',status,'redeemed_by',resgatado_por,'expires_at',expira_em,'redeemed_at',resgatado_em) FROM estudo.vouchers WHERE id=200),
'products',(SELECT jsonb_agg(jsonb_build_object('id',id,'code',codigo,'status',status,'publication',publicacao_id) ORDER BY id) FROM estudo.produtos WHERE id IN(1,2)),
'counts',jsonb_build_object('user_grants',(SELECT count(*) FROM estudo.acessos WHERE usuario_id=492),'user_active_grants',(SELECT count(*) FROM estudo.acessos WHERE usuario_id=492 AND status='ACTIVE'),'user_benefits',(SELECT count(*) FROM estudo.beneficios WHERE usuario_id=492),'user_eligible_benefits',(SELECT count(*) FROM estudo.beneficios WHERE usuario_id=492 AND status='ELIGIBLE'),'voucher_grants',(SELECT count(*) FROM estudo.acessos WHERE voucher_id=200),'voucher_benefits',(SELECT count(*) FROM estudo.beneficios b JOIN estudo.acessos a ON a.id=b.acesso_id WHERE a.voucher_id=200)),
'grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'user_id',a.usuario_id,'product_id',a.produto_id,'voucher_id',a.voucher_id,'status',a.status,'granted_at',a.concedido_em) ORDER BY a.id),'[]'::jsonb) FROM estudo.acessos a WHERE a.usuario_id=492 OR a.voucher_id=200),
'benefits',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'user_id',b.usuario_id,'product_id',b.produto_id,'access_id',b.acesso_id,'percent',b.percentual,'status',b.status) ORDER BY b.id),'[]'::jsonb) FROM estudo.beneficios b WHERE b.usuario_id=492 OR b.acesso_id IN(SELECT id FROM estudo.acessos WHERE voucher_id=200)),
'audit',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'actor_id',x.ator_id,'action',x.acao,'entity',x.entidade,'entity_id',x.entidade_id,'created_at',x.criado_em,'access_id',x.detalhes->'access_id','voucher_id',x.detalhes->'voucher_id','campaign_id',x.detalhes->'campaign_id','campaign',x.detalhes->'campaign','percent',x.detalhes->'percent','kind',x.detalhes->'kind','status',x.detalhes->'status','version',x.detalhes->'version') ORDER BY x.id),'[]'::jsonb) FROM estudo.auditoria_comercial x WHERE (x.entidade='voucher' AND x.entidade_id=200) OR (x.entidade='campaign' AND x.entidade_id=1 AND x.acao='CAMPAIGN_STATUS') OR (x.ator_id=492 AND x.acao IN('REDEEM','ANNUAL_EARLY_PURCHASE_BENEFIT')) OR (x.entidade='access' AND x.entidade_id IN(SELECT id FROM estudo.acessos WHERE voucher_id=200)) OR (x.entidade='benefit' AND x.entidade_id IN(SELECT b.id FROM estudo.beneficios b JOIN estudo.acessos a ON a.id=b.acesso_id WHERE a.voucher_id=200)))
)::text AS payload